Lemma rw_cells_C8_zero_split : forall m A cs, rw_cells bsegs m A (C8 (wz 0) :: cs) -> rw_cells bsegs m A (C4 (wz 0) :: C4 (wz 0) :: cs).
Proof. intros m A cs [[[_ W] B] R]. exact (conj (conj (conj I (conj I W)) B) R). Qed.

